const input=document.getElementById("text-input"),output=document.getElementById("text-output");function toCase(t){const e=input.value;if(!e)return output.textContent=i18n.t("common.enter_text");let o="";switch(t){case"upper":o=e.toUpperCase();break;case"lower":o=e.toLowerCase();break;case"capital":o=e.toLowerCase().replace(/(?:^|\s)\S/g,n=>n.toUpperCase());break;case"snake":o=e.trim().replace(/\s+/g,"_").toLowerCase();break;case"camel":o=e.toLowerCase().replace(/[^a-zA-Z0-9]+(.)/g,(n,a)=>a.toUpperCase());break}output.textContent=o,output.style.color="var(--text)"}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"converted-text.txt")}function clearAll(){input.value="",output.textContent=i18n.t("common.result_placeholder"),output.style.color="var(--text-muted)"}
